from os.path import join, isdir, exists, splitext


def f_303200(directory):
    if not isdir(directory):
        raise NotADirectoryError

    for root, dirs, files in walk(directory):
        for name in files:
            remove(join(root, name))
        for name in dirs:
            remove(join(root, name))

        remove(directory)

