def f_21171(list):
    """二次元リスト`list`から重複する要素のみ抽出する
    """
    result = []
    seen = set()

    for inner_list in list:
        for item in inner_list:
            if item in seen and item not in result:
                result.append(item)
            else:
                seen.add(item)

    return result

def f_21171(list):
    """2次元listsから重複する要素のみabstractする"""
    if type(list) == list:
        list = set(list)
        for i in list:
            for j in list:
                if i == j:
                    list.remove(j)
        return list
    else:
